#!/usr/bin/env python3
"""Recompute deterministic Barren Island ash-plume gate ground truth."""

from __future__ import annotations

import html
import json
import re
from datetime import datetime
from pathlib import Path
from typing import Any


TASK_ID = "CSX-306_Q1"
PACKAGE_ID = "CSX-306"
TARGET_FAMILY = "barren_island_ash_plume_rain_change_gate_consistency"

SOURCE_FILES = [
    "metadata/event.json",
    "data/event_reports/event_reports_001_Locked_package_evidence_report.html",
    "data/event_reports/event_reports_003_Locked_event_anchor_2010_Barren_Island_ash_plume.json",
    "data/physical_hazard/physical_hazard_001_NASA_POWER_daily_point_sample.json",
    "data/physical_hazard/physical_hazard_002_Open-Meteo_archive_point_sample.json",
    "data/physical_hazard/physical_hazard_003_ERA5-Land_hourly_aggregate_stats.json",
    "data/physical_hazard/physical_hazard_005_GPM_IMERG_V07_event_accumulated_precipitation.json",
    "data/physical_hazard/physical_hazard_007_CHIRPS_daily_event_accumulated_precipitation.json",
    "data/remote_sensing/remote_sensing_002_Sentinel-1_GRD_VV_pre_post_change.json",
    "data/physical_hazard/physical_hazard_009_Sentinel-2_SR_Harmonized_dNBR.json",
]


def repo_root() -> Path:
    return Path(__file__).resolve().parents[3]


def task_dir() -> Path:
    return Path(__file__).resolve().parent


def package_root() -> Path:
    return repo_root() / "event_packages" / "standard_event_packages" / "packages" / PACKAGE_ID


def read_json(root: Path, rel_path: str) -> Any:
    return json.loads((root / rel_path).read_text(encoding="utf-8-sig"))


def raw_html(root: Path, rel_path: str) -> str:
    return (root / rel_path).read_text(encoding="utf-8", errors="ignore")


def html_to_text(raw: str) -> str:
    text = re.sub(r"(?is)<script.*?</script>|<style.*?</style>", " ", raw)
    text = re.sub(r"(?s)<[^>]+>", " ", text)
    return re.sub(r"\s+", " ", html.unescape(text)).strip()


def meta_content(raw: str, name_or_property: str) -> str:
    pattern = (
        r'<meta\s+(?:name|property)="'
        + re.escape(name_or_property)
        + r'"\s+content="([^"]+)"'
    )
    match = re.search(pattern, raw, flags=re.I)
    return html.unescape(match.group(1)).strip() if match else ""


def parse_date(value: str) -> datetime:
    for fmt in ("%Y-%m-%d", "%B %d, %Y"):
        try:
            return datetime.strptime(value, fmt)
        except ValueError:
            pass
    raise ValueError(f"unrecognized date: {value}")


def report_fields(root: Path) -> dict[str, Any]:
    raw = raw_html(root, "data/event_reports/event_reports_001_Locked_package_evidence_report.html")
    text = html_to_text(raw)
    acquired = re.search(r"This image was acquired on ([A-Za-z]+ \d{1,2}, \d{4}),", text)
    description = meta_content(raw, "description") or meta_content(raw, "og:description")
    return {
        "description": description,
        "report_image_date": acquired.group(1) if acquired else "",
        "small_ash_phrase_present": "small plume of ash" in description.lower(),
        "ash_plume_sentence_present": "A plume of ash rises from Barren Island Volcano" in text,
    }


def rounded(value: float, digits: int = 3) -> float:
    return round(float(value), digits)


def build_rubric() -> dict[str, Any]:
    return {
        "total_points": 20,
        "criteria": [
            {
                "name": "Answer form",
                "points": 3,
                "description": "Returns compact JSON with the requested numeric fields, final classification, and one short computed consequence.",
                "partial_credit": "Award 1-2 points if the values are recoverable but field names or nesting differ.",
            },
            {
                "name": "Timing term",
                "points": 4,
                "description": "Computes the report image date, locked event start, and date offset correctly: 2010-09-25 minus 2010-09-03 equals 22 days.",
                "partial_credit": "Award 1-3 points for finding the two dates but making a small arithmetic or direction error.",
            },
            {
                "name": "Rain aggregation",
                "points": 4,
                "description": "Computes point_precip_mean_mm = 13.645, regional_peak_precip_mm = 184.585, and peak_to_point_ratio = 13.528 within tolerance.",
                "partial_credit": "Award about 1 point for each correct precipitation component and 1 point for the ratio.",
            },
            {
                "name": "Change-scene count",
                "points": 3,
                "description": "Computes change_scene_total = 0 from the four radar and optical pre/post counts.",
                "partial_credit": "Award 1-2 points for finding the zero-count products but summing only one sensor.",
            },
            {
                "name": "Gate score",
                "points": 4,
                "description": "Applies the four threshold tests correctly and reports rain_change_gate_score = 1.",
                "partial_credit": "Award 1 point per correctly evaluated threshold test.",
            },
            {
                "name": "Computed consequence",
                "points": 2,
                "description": "Returns source_proximal_ash_anchor_controls and rejects rain_or_change_context_controls from the score being below 3.",
                "partial_credit": "Award 1 point for the correct rejection with incomplete wording.",
            },
        ],
    }


def build_output() -> dict[str, Any]:
    root = package_root()
    event = read_json(root, "metadata/event.json")
    anchor = read_json(
        root,
        "data/event_reports/event_reports_003_Locked_event_anchor_2010_Barren_Island_ash_plume.json",
    )
    power = read_json(root, "data/physical_hazard/physical_hazard_001_NASA_POWER_daily_point_sample.json")
    open_meteo = read_json(root, "data/physical_hazard/physical_hazard_002_Open-Meteo_archive_point_sample.json")
    era5 = read_json(root, "data/physical_hazard/physical_hazard_003_ERA5-Land_hourly_aggregate_stats.json")
    gpm = read_json(root, "data/physical_hazard/physical_hazard_005_GPM_IMERG_V07_event_accumulated_precipitation.json")
    chirps = read_json(root, "data/physical_hazard/physical_hazard_007_CHIRPS_daily_event_accumulated_precipitation.json")
    sentinel1 = read_json(root, "data/remote_sensing/remote_sensing_002_Sentinel-1_GRD_VV_pre_post_change.json")
    sentinel2 = read_json(root, "data/physical_hazard/physical_hazard_009_Sentinel-2_SR_Harmonized_dNBR.json")

    report = report_fields(root)
    locked_start = anchor["locked_event_anchor"]["event_start_date"]
    date_offset_days = (parse_date(report["report_image_date"]) - parse_date(locked_start)).days

    power_precip = float(power["properties"]["parameter"]["PRECTOTCORR"]["20100903"])
    open_meteo_precip = float(open_meteo["daily"]["precipitation_sum"][0])
    point_precip_mean = rounded((power_precip + open_meteo_precip) / 2.0)

    regional_peaks = {
        "chirps_event_precip_mm_max": rounded(chirps["stats"]["chirps_event_precip_mm_max"]),
        "era5_precipitation_sum_mm_max": rounded(era5["stats"]["precipitation_sum_mm_max"]),
        "gpm_event_precip_mm_max": rounded(gpm["stats"]["gpm_event_precip_mm_max"]),
    }
    regional_peak = max(regional_peaks.values())
    peak_to_point_ratio = rounded(regional_peak / point_precip_mean)

    change_counts = {
        "radar_pre_count": int(sentinel1["counts"]["pre_count"]),
        "radar_post_count": int(sentinel1["counts"]["post_count"]),
        "optical_pre_count": int(sentinel2["counts"]["pre_count"]),
        "optical_post_count": int(sentinel2["counts"]["post_count"]),
    }
    change_scene_total = sum(change_counts.values())

    thresholds = {
        "point_mean_min_mm": 25,
        "regional_peak_min_mm": 100,
        "date_offset_max_days": 3,
        "change_scene_min": 1,
        "score_min_for_context_controls": 3,
    }
    tests = {
        "point_rain": point_precip_mean >= thresholds["point_mean_min_mm"],
        "regional_peak": regional_peak >= thresholds["regional_peak_min_mm"],
        "date_alignment": date_offset_days <= thresholds["date_offset_max_days"],
        "change_scenes": change_scene_total >= thresholds["change_scene_min"],
    }
    gate_score = sum(1 for passed in tests.values() if passed)
    classification = (
        "rain_or_change_context_controls"
        if gate_score >= thresholds["score_min_for_context_controls"]
        else "source_proximal_ash_anchor_controls"
    )

    metrics = {
        "date_offset_days": date_offset_days,
        "point_precip_mean_mm": point_precip_mean,
        "regional_peak_precip_mm": regional_peak,
        "peak_to_point_ratio": peak_to_point_ratio,
        "change_scene_total": change_scene_total,
        "rain_change_gate_score": gate_score,
    }

    return {
        "schema_version": "1.0",
        "task_id": TASK_ID,
        "event_id": PACKAGE_ID,
        "target_family": TARGET_FAMILY,
        "task_type": "numeric",
        "evaluation_mode": "deterministic",
        "difficulty_level": "L3",
        "primary_gt": {
            "answer": classification,
            "target_family": TARGET_FAMILY,
            "metrics": metrics,
            "thresholds": thresholds,
            "tests": tests,
            "tolerances": {
                "point_precip_mean_mm": 0.001,
                "regional_peak_precip_mm": 0.001,
                "peak_to_point_ratio": 0.001,
                "date_offset_days": 0,
                "change_scene_total": 0,
                "rain_change_gate_score": 0,
            },
            "rejected": "rain_or_change_context_controls",
        },
        "event": {
            "package_id": PACKAGE_ID,
            "event_name": event["event_name"],
            "hazard_family": event["hazard_family"],
            "event_date_or_window": f"{locked_start} to {anchor['locked_event_anchor']['event_end_date']}",
            "location": anchor["locked_event_anchor"]["event_location"],
        },
        "decision_rule": {
            "summary": "Compute a four-test gate for whether rain context and change-map availability can control the Barren Island ash-plume classification.",
            "requires_computation": True,
            "score_rule": "The context-controls label requires at least three passed tests; this event passes one.",
            "final_label": classification,
        },
        "key_values": {
            "report": report,
            "locked_event_start": locked_start,
            "point_precip_inputs_mm": {
                "power": power_precip,
                "open_meteo": open_meteo_precip,
            },
            "regional_peak_inputs_mm": regional_peaks,
            "change_counts": change_counts,
            "gate_tests": tests,
        },
        "numeric_tolerances": {
            "date_offset_days": {"target": date_offset_days, "absolute_tolerance": 0},
            "point_precip_mean_mm": {"target": point_precip_mean, "absolute_tolerance": 0.001},
            "regional_peak_precip_mm": {"target": regional_peak, "absolute_tolerance": 0.001},
            "peak_to_point_ratio": {"target": peak_to_point_ratio, "absolute_tolerance": 0.001},
            "change_scene_total": {"target": change_scene_total, "absolute_tolerance": 0},
            "rain_change_gate_score": {"target": gate_score, "absolute_tolerance": 0},
        },
        "rubric": build_rubric(),
        "provenance": {
            "computed_by": "compute_gt.py",
            "source_files": SOURCE_FILES,
            "notes": "All scored values are recomputed from local CSX-306 dates, precipitation summaries, and change-scene counts.",
        },
    }


def main() -> None:
    output = build_output()
    out_path = task_dir() / "computed_gt.json"
    out_path.write_text(json.dumps(output, ensure_ascii=True, indent=2, sort_keys=True) + "\n", encoding="utf-8")


if __name__ == "__main__":
    main()
